import { useScrollAnimation } from '../hooks/useScrollAnimation';
import './skills.css';

const categories = [
  {
    label: 'Languages',
    color: '#6366f1',
    skills: ['Python', 'TypeScript', 'JavaScript', 'C#', 'C++', 'HTML', 'CSS'],
  },
  {
    label: 'Backend',
    color: '#a855f7',
    skills: ['Node.js', '.NET Core', 'Flask', 'NestJS', 'REST APIs', 'GraphQL'],
  },
  {
    label: 'Frontend',
    color: '#22d3ee',
    skills: ['React.js', 'Angular', 'Tailwind CSS', 'Bootstrap', 'Redux'],
  },
  {
    label: 'Databases & Cloud',
    color: '#10b981',
    skills: ['PostgreSQL', 'MySQL', 'MongoDB', 'AWS', 'GCP (BigQuery, DataFlow)', 'SSMS'],
  },
  {
    label: 'AI & ML',
    color: '#f59e0b',
    skills: ['TensorFlow', 'PyTorch', 'OpenCV', 'Scikit-learn', 'Deep Learning', 'Computer Vision'],
  },
  {
    label: 'DevOps & Tools',
    color: '#ec4899',
    skills: ['Docker', 'Git', 'CI/CD Pipelines', 'Webpack', 'Postman', 'Hadoop', 'PySpark'],
  },
];

const Skills = () => {
  const [headerRef, headerIn] = useScrollAnimation();

  return (
    <section id="skills" className="skills-section">
      <div className="container">
        <div ref={headerRef} className={`animate ${headerIn ? 'in-view' : ''}`}>
          <span className="section-label">Toolkit</span>
          <h2 className="section-title">
            Skills & <span className="gradient-text">Expertise</span>
          </h2>
          <p className="section-sub">
            Technologies I've used across production systems, research projects, and freelance work.
          </p>
        </div>

        <div className="skills-grid">
          {categories.map((cat, i) => (
            <SkillCard key={cat.label} cat={cat} index={i} />
          ))}
        </div>
      </div>
    </section>
  );
};

function SkillCard({ cat, index }) {
  const [ref, inView] = useScrollAnimation();
  return (
    <div ref={ref} className={`skill-cat glass-card animate d${(index % 3) + 1} ${inView ? 'in-view' : ''}`}>
      <div className="skill-cat-header">
        <span className="skill-cat-dot" style={{ background: cat.color }} />
        <h3 className="skill-cat-name">{cat.label}</h3>
      </div>
      <div className="skill-tags">
        {cat.skills.map(s => (
          <span key={s} className="skill-pill" style={{ '--pill-color': cat.color }}>
            {s}
          </span>
        ))}
      </div>
    </div>
  );
}

export default Skills;
